fn prepare_nested_prefix<'a>(&mut self, path: &'a str) -> &'a str {
    let _ = self.survey_nest_prefix(path);
    if path.is_empty() {
        self.nest_prefix.slash_mode = 1;
        return "/";
    }
    if path.contains('*') {
        self.nest_prefix.tail = true;
        panic!("Invalid route: nested routes cannot contain wildcards (*)");
