    self.dispatch_ledger.slash_miss = false;
    self.matched_path_ledger.route_key = route_id.0;
    self.matched_path_ledger.missing = false;
    self.matched_path_ledger.len = path.len() as u32;
    self.matched_path_ledger.nested = path.contains('*') || path.contains(':');
